mapper.select:
SELECT /* kr.or.kids.domain.cm.community.faq.mapper.selectFaqList */ A.faq_sn AS faqSn , A.task_se_cd AS taskSeCd , A.faq_clsf_nm AS faqClsfNm , A.faq_ttl AS faqTtl , A.faq_seq AS faqSeq , A.use_yn AS useYn , A.lang_se_cd AS langSeId , A.faq_ans_cn AS faqAnsCn , A.atch_file_id AS atchFileId , A.wrtr_dept_nm AS wrtrDeptNm , A.mdfr_dept_nm AS mdfrDeptNm , COALESCE(E.emp_nm, A.rgtr_id) AS rgtrId , TO_CHAR(A.reg_dt, 'YYYY-MM-DD') AS regDt , A.mdfr_id AS mdfrId , TO_CHAR(A.mdfcn_dt, 'YYYY-MM-DD') AS mdfcnDt , COALESCE(A.pst_inq_cnt, 0) AS pstInqCnt , A.faq_se_cd AS faqSeCd , C.com_dtl_cd_nm AS faqSeNm FROM kids_own.tb_cm_m_faq A LEFT JOIN kids_own.tb_pp_m_mngr_info M ON M.emp_no = A.rgtr_id LEFT JOIN kids_own.tb_pp_m_emp_info E ON E.emp_no = M.emp_no LEFT JOIN kids_own.tb_ca_c_dtl_code C ON C.com_dtl_cd = A.faq_se_cd AND C.com_group_cd = 'CMCMM00005' WHERE 1=1
AND A.task_se_cd = #{taskSeCd}
AND A.lang_se_cd = #{langSeId}
AND A.faq_se_cd = #{faqSeCd}
AND A.use_yn = #{useYn}
AND A.faq_ttl LIKE '%' || #{searchKeyword} || '%'
AND A.rgtr_id IN ( SELECT ei.emp_no FROM kids_own.tb_pp_m_emp_info ei WHERE ei.emp_nm LIKE '%' || #{searchKeyword} || '%' )
AND A.faq_ans_cn LIKE '%' || #{searchKeyword} || '%'
ORDER BY A.faq_seq ASC, A.faq_sn DESC LIMIT #{pageSize} OFFSET (#{page} - 1) * #{pageSize}

SELECT /* kr.or.kids.domain.cm.community.faq.mapper.selectFaqListCount */
       COUNT(*)
  FROM kids_own.tb_cm_m_faq A
 WHERE 1=1

   AND A.task_se_cd = #{taskSeCd}


   AND A.lang_se_cd = #{langSeId}


   AND A.faq_se_cd = #{faqSeCd}


   AND A.use_yn = #{useYn}





            AND A.faq_ttl LIKE '%' || #{searchKeyword} || '%'


            AND A.faq_ans_cn LIKE '%' || #{searchKeyword} || '%'

mapper.update:
/* kr.or.kids.domain.cm.community.faq.mapper.updateFaqViewCount */
UPDATE kids_own.tb_cm_m_faq
   SET pst_inq_cnt = COALESCE(pst_inq_cnt, 0) + 1
     , mdfcn_dt = NOW()
WHERE faq_sn = #{faqSn}
